function actionFieldConfig(field: string): AplHelpers.APLPickerBuilderFieldConfig<any, any> {
	return {
		field: field,
		newValue: APLValue.create,
		factory: (parent, player, config) => new APLActionPicker(parent, player, config),
	};
}

function actionListFieldConfig(field: string): AplHelpers.APLPickerBuilderFieldConfig<any, any> {
	return {
		field: field,
		newValue: () => [],
		factory: (parent, player, config) => new ListPicker<Player<any>, APLAction>(parent, player, {
			...config,
			// Override setValue to replace undefined elements with default messages.
			setValue: (eventID: EventID, player: Player<any>, newValue: Array<APLAction>) => {
				config.setValue(eventID, player, newValue.map(val => val || APLAction.create()));
			},
			itemLabel: 'Action',
			newItem: APLAction.create,
			copyItem: (oldValue: APLAction) => oldValue ? APLAction.clone(oldValue) : oldValue,
			newItemPicker: (parent: HTMLElement, listPicker: ListPicker<Player<any>, APLAction>, index: number, config: ListItemPickerConfig<Player<any>, APLAction>) => new APLActionPicker(parent, player, config),
			allowedActions: ['create', 'delete', 'move'],
			actions: {
				create: {
					useIcon: true,
				}
			}
		}),
	};
}


function warlockPetCommandFieldConfig(field: string): AplHelpers.APLPickerBuilderFieldConfig<any, any> {
	return {
		field: field,
		newValue: () => ({ oneofKind: 'petAttack', petAttack: WarlockActionPetAttack.create() }),
		// The dropdown's value type must match the field type (the WarlockAction
		// 'action' oneof wrapper), because TextDropdownPicker has no source<->value
		// projection (V == T). Using projected primitives (e.g. the oneofKind
		// string) works for live edits but breaks on reload, because the parent
		// APLPickerBuilder round-trips the raw wrapper object through
		// setInputValue/getInputValue - it wouldn't match a string option and the
		// picker would collapse to the default. So the option values ARE wrappers,
		// compared by oneofKind, and we rely on the framework's getValue/setValue.
		factory: (parent, player, config) => new TextDropdownPicker(parent, player, {
			...config,
			defaultLabel: 'Attack',
			equals: (a, b) => a?.oneofKind == b?.oneofKind,
			values: [
				{ value: { oneofKind: 'petAttack', petAttack: WarlockActionPetAttack.create() }, label: 'Attack' },
				{ value: { oneofKind: 'petPassive', petPassive: WarlockActionPetPassive.create() }, label: 'Passive' },
			],
		}),
	};
}

function hunterWeaveMeleeFieldConfig(field: string): AplHelpers.APLPickerBuilderFieldConfig<any, any> {
	return {
		field: field,
		newValue: () => ({ oneofKind: 'weave', weave: HunterActionWeave.create({ melee: true }) }),
		// The dropdown value type must match the field type (the HunterAction
		// 'action' oneof wrapper) so it round-trips through the parent
		// APLPickerBuilder on reload - see warlockPetCommandFieldConfig for the
		// full explanation. Projecting to a bare bool broke persistence: on
		// refresh both weave actions collapsed to the default.
		factory: (parent, player, config) => new TextDropdownPicker(parent, player, {
			...config,
			defaultLabel: 'Ranged',
			equals: (a, b) => a?.weave?.melee == b?.weave?.melee,
			values: [
				{ value: { oneofKind: 'weave', weave: HunterActionWeave.create({ melee: true }) }, label: 'Melee' },
				{ value: { oneofKind: 'weave', weave: HunterActionWeave.create({ melee: false }) }, label: 'Ranged' },
			],
		}),
	};
}

function inputBuilder<T>(config: {
	label: string,
	submenu?: Array<string>,
	shortDescription: string,
	fullDescription?: string,
	includeIf?: (player: Player<any>, isPrepull: boolean) => boolean,
	newValue: () => T,
	fields: Array<AplHelpers.APLPickerBuilderFieldConfig<T, any>>,
}): ActionKindConfig<T> {
	return {
		label: config.label,
		submenu: config.submenu,
		shortDescription: config.shortDescription,
		fullDescription: config.fullDescription,
		includeIf: config.includeIf,
		newValue: config.newValue,
		factory: AplHelpers.aplInputBuilder(config.newValue, config.fields),
	};
}

