import {
	ProgressMetrics,
	RaidSimRequest,
	RaidSimRequestSplitRequest,
	RaidSimResult,
	RaidSimResultCombinationRequest,
	StatWeightsCalcRequest,
	StatWeightsRequest,
	StatWeightsResult,
	StatWeightsStatResultData,
} from './proto/api.js';
import { WorkerPool } from './worker_pool.js';

// Multi-core sims, ported from the Cata/MoP sims: each web worker runs its own copy of the sim, so
// one sim is split into one smaller sim per worker and the results are merged afterwards. Every
// iteration reseeds to seed+i and the splits continue each other's seeds, so the merged result is
// the same as a single-worker run.

const PROGRESS_INTERVAL_MS = 100;

/**
 * Runs a raid sim split over all workers in the pool. Progress callbacks only report progress;
 * the merged result is returned (and sent once more as the final progress update).
 */
export async function runConcurrentSim(request: RaidSimRequest, workerPool: WorkerPool, onProgress: Function): Promise<RaidSimResult> {
	const totalIterations = request.simOptions!.iterations;
	const split = await workerPool.raidSimRequestSplit(RaidSimRequestSplitRequest.create({
		splitCount: workerPool.getNumWorkers(),
		request: request,
	}));
	if (split.errorResult) {
		return finishWithError(split.errorResult, onProgress);
	}

	const numSplits = split.requests.length;
	const iterationsDone: Array<number> = new Array(numSplits).fill(0);
	const dps: Array<number> = new Array(numSplits).fill(0);
	const hps: Array<number> = new Array(numSplits).fill(0);
	const presimRunning: Array<boolean> = new Array(numSplits).fill(false);

	const mergedProgress = (): ProgressMetrics => {
		const completed = iterationsDone.reduce((a, b) => a + b, 0);
		const weighted = (values: Array<number>) => completed ? values.reduce((sum, v, i) => sum + v * iterationsDone[i], 0) / completed : 0;
		return ProgressMetrics.create({
			totalIterations: totalIterations,
			completedIterations: completed,
			presimRunning: presimRunning.some(p => p),
			dps: weighted(dps),
			hps: weighted(hps),
		});
	};

	let lastReport = 0;
	const results = await Promise.all(split.requests.map((splitRequest, i) =>
		workerPool.raidSimAsync(splitRequest, (pm: ProgressMetrics) => {
			presimRunning[i] = pm.presimRunning;
			if (pm.completedIterations > 0) {
				iterationsDone[i] = pm.completedIterations;
				dps[i] = pm.dps;
				hps[i] = pm.hps;
			}
			// A split's own final result is not the final result of the whole sim.
			if (pm.finalRaidResult) {
				return;
			}
			const now = Date.now();
			if (now - lastReport >= PROGRESS_INTERVAL_MS) {
				lastReport = now;
				onProgress(mergedProgress());
			}
		})));

	const errored = results.find(r => !r || r.errorResult);
	if (errored) {
		return finishWithError(errored?.errorResult || 'A split sim returned no result.', onProgress);
	}

	const combined = numSplits == 1 ? results[0] : await workerPool.raidSimResultCombination(RaidSimResultCombinationRequest.create({ results: results }));
	if (combined.errorResult) {
		return finishWithError(combined.errorResult, onProgress);
	}

	const final = mergedProgress();
	final.completedIterations = totalIterations;
	final.dps = combined.raidMetrics?.dps?.avg ?? final.dps;
	final.hps = combined.raidMetrics?.hps?.avg ?? final.hps;
	final.finalRaidResult = combined;
	onProgress(final);
	return combined;
}

function finishWithError(errorResult: string, onProgress: Function): RaidSimResult {
	console.error(errorResult);
	const result = RaidSimResult.create({ errorResult: errorResult });
	onProgress(ProgressMetrics.create({ finalRaidResult: result }));
	return result;
}

/**
 * Stat weights on all workers: the baseline and every stat's low/high sim run one after another,
 * each split over the whole pool, then one worker computes the weights from their results.
 */
export async function runConcurrentStatWeights(request: StatWeightsRequest, workerPool: WorkerPool, onProgress: Function): Promise<StatWeightsResult> {
	const data = await workerPool.statWeightRequests(request);
	if (data.errorResult || !data.baseRequest) {
		return weightsError(data.errorResult || 'Could not build the stat weight sims.', onProgress);
	}

	const sims: Array<RaidSimRequest> = [data.baseRequest];
	for (const statSims of data.statSimRequests) {
		sims.push(statSims.requestLow!, statSims.requestHigh!);
	}
	const totalIterations = sims.reduce((sum, sim) => sum + sim.simOptions!.iterations, 0);

	let iterationsBefore = 0;
	const results: Array<RaidSimResult> = [];
	for (const sim of sims) {
		const completedSims = results.length;
		const result = await runConcurrentSim(sim, workerPool, (pm: ProgressMetrics) => {
			if (pm.finalRaidResult) {
				return;
			}
			onProgress(ProgressMetrics.create({
				totalIterations: totalIterations,
				completedIterations: iterationsBefore + pm.completedIterations,
				completedSims: completedSims,
				totalSims: sims.length,
			}));
		});
		if (result.errorResult) {
			return weightsError(result.errorResult, onProgress);
		}
		results.push(result);
		iterationsBefore += sim.simOptions!.iterations;
	}

	const weights = await workerPool.statWeightCompute(StatWeightsCalcRequest.create({
		baseResult: results[0],
		epReferenceStat: data.epReferenceStat,
		statSimResults: data.statSimRequests.map((statSims, i) => StatWeightsStatResultData.create({
			statData: statSims.statData,
			resultLow: results[1 + 2 * i],
			resultHigh: results[2 + 2 * i],
		})),
	}));

	onProgress(ProgressMetrics.create({
		totalIterations: totalIterations,
		completedIterations: totalIterations,
		completedSims: sims.length,
		totalSims: sims.length,
		finalWeightResult: weights,
	}));
	return weights;
}

function weightsError(errorResult: string, onProgress: Function): StatWeightsResult {
	console.error(errorResult);
	const result = StatWeightsResult.create({ errorResult: errorResult });
	onProgress(ProgressMetrics.create({ finalWeightResult: result }));
	return result;
}
